import { Component, computed, inject, input, signal, viewChild } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { ClientContacts } from '../contacts/client-contacts';
import { Contact } from '../contacts/contact.service';
import { ClientPaymentForm } from '../payments/client-payment';
import { ClientProjects } from '../projects/client-projects';
import { ClientService } from './client.service';

// A single client's page: their name, email and main contact, a link to their statement, a form to record a lump payment split across their invoices, counts of their projects and contacts, their contacts, and the projects being done for them.
@Component({
  selector: 'app-client-detail',
  imports: [RouterLink, ClientContacts, ClientProjects, ClientPaymentForm],
  styles: `
    .client-badges {
      display: flex;
      gap: 1rem;
      padding: 0;
      list-style: none;
    }
  `,
  template: `
    <a routerLink="/clients" data-testid="client-back">Back to clients</a>
    @if (client.error()) {
      <p role="alert" data-testid="client-error">Could not load the client.</p>
    } @else if (client.value(); as c) {
      <h1 data-testid="client-detail-name">{{ c.name }}</h1>
      <p>Email: <span data-testid="client-detail-email">{{ c.email }}</span></p>
      <p>
        Main contact:
        @if (c.primaryContact; as primary) {
          <span data-testid="client-primary-contact">{{ primary.name }}</span>
        } @else {
          <span data-testid="client-primary-contact-none">None chosen</span>
        }
      </p>
      @if (summary.hasValue()) {
        <ul class="client-badges" aria-label="At a glance" data-testid="client-badges">
          <li>
            Jobs: <span data-testid="client-projects-count">{{ summary.value().projectCount }}</span>
          </li>
          <li>
            Contacts: <span data-testid="client-contacts-count">{{ summary.value().contactCount }}</span>
          </li>
        </ul>
      }
      <p>
        <a [routerLink]="['/clients', clientId(), 'statement']" data-testid="client-statement-open">View statement</a>
      </p>
      <p>
        <button
          type="button"
          data-testid="client-record-payment"
          aria-controls="client-payment-panel"
          [attr.aria-expanded]="recordingPayment()"
          (click)="recordingPayment.set(!recordingPayment())"
        >
          {{ recordingPayment() ? 'Close payment form' : 'Record a payment' }}
        </button>
      </p>
      <div id="client-payment-panel">
        @if (recordingPayment()) {
          <app-client-payment [clientId]="clientId()" (recorded)="paymentRecorded()" />
        }
        @if (paymentSaved()) {
          <p role="status" data-testid="client-payment-recorded">Payment recorded.</p>
        }
      </div>
      <app-client-contacts
        [clientId]="clientId()"
        (contactAdded)="contactAdded()"
        (primaryChanged)="primaryChanged($event)"
      />
      <app-client-projects [clientId]="clientId()" />
    }
  `,
})
export class ClientDetail {
  private readonly service = inject(ClientService);

  /** Bound from the `:id` route parameter. */
  readonly id = input.required<string>();
  protected readonly clientId = computed(() => Number(this.id()));

  protected readonly client = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.get(params),
  });

  protected readonly summary = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.summary(params),
  });

  protected readonly recordingPayment = signal(false);
  protected readonly paymentSaved = signal(false);
  private readonly paymentForm = viewChild(ClientPaymentForm);

  /** Resolves to true once any payment being recorded has been saved, so the page can be left safely. */
  async canLeave(): Promise<boolean> {
    await this.paymentForm()?.settled();
    return true;
  }

  protected paymentRecorded(): void {
    this.recordingPayment.set(false);
    this.paymentSaved.set(true);
    this.client.reload();
  }

  protected contactAdded(): void {
    this.summary.reload();
    // The first contact added becomes the main contact.
    if (!this.client.value()?.primaryContact) {
      this.client.reload();
    }
  }

  protected primaryChanged(contact: Contact): void {
    this.client.update((c) => c && { ...c, primaryContact: { id: contact.id, name: contact.name } });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Client {
  id: number;
  name: string;
  email: string;
  archived: boolean;
  /** The client's main contact; null until one is chosen. */
  primaryContact: { id: number; name: string } | null;
  /** What is left to pay on the client's sent, not yet fully paid invoices. */
  outstanding: number;
}

/** At-a-glance counts of what one client has. */
export interface ClientSummary {
  projectCount: number;
  contactCount: number;
}

export type NewClient = Omit<Client, 'id' | 'archived' | 'primaryContact' | 'outstanding'>;

@Injectable({ providedIn: 'root' })
export class ClientService {
  private readonly http = inject(HttpClient);

  list(includeArchived = false): Observable<Client[]> {
    return this.http.get<Client[]>('/api/clients', { params: { includeArchived } });
  }

  get(id: number): Observable<Client> {
    return this.http.get<Client>(`/api/clients/${id}`);
  }

  summary(id: number): Observable<ClientSummary> {
    return this.http.get<ClientSummary>(`/api/clients/${id}/summary`);
  }

  create(client: NewClient): Observable<Client> {
    return this.http.post<Client>('/api/clients', client);
  }

  update(id: number, client: NewClient): Observable<Client> {
    return this.http.put<Client>(`/api/clients/${id}`, client);
  }

  archive(id: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/archive`, null);
  }

  restore(id: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/restore`, null);
  }
}
import { Routes } from '@angular/router';

// The route table. A page is a new component file registered here with one entry that lazily
// imports it; an entry's `data: { section, label }` is read by the shell to build the nav bar.
export const routes: Routes = [
  { path: '', redirectTo: 'home', pathMatch: 'full' },
  {
    path: 'home',
    data: { section: 'home', label: 'Home', order: 0 },
    loadComponent: () => import('./features/home/home').then((m) => m.Home),
  },
  {
    path: 'dashboard',
    data: { section: 'dashboard', label: 'Dashboard', order: 0 },
    loadComponent: () => import('./features/dashboard/dashboard').then((m) => m.Dashboard),
  },
  {
    path: 'clients',
    data: { section: 'clients', label: 'Clients', order: 1 },
    loadComponent: () => import('./features/clients/clients').then((m) => m.Clients),
  },
  {
    path: 'clients/:id',
    // Wait for a payment being recorded to be saved before leaving, so other pages see it.
    canDeactivate: [(page: { canLeave(): Promise<boolean> }) => page.canLeave()],
    loadComponent: () => import('./features/clients/client-detail').then((m) => m.ClientDetail),
  },
  {
    path: 'clients/:id/statement',
    loadComponent: () => import('./features/invoices/client-statement').then((m) => m.ClientStatement),
  },
  {
    path: 'projects',
    data: { section: 'projects', label: 'Jobs', order: 2 },
    loadComponent: () => import('./features/projects/projects').then((m) => m.Projects),
  },
  {
    path: 'invoices',
    data: { section: 'invoices', label: 'Invoices', order: 3 },
    loadComponent: () => import('./features/invoices/invoices').then((m) => m.Invoices),
  },
  {
    path: 'projects/:id',
    loadComponent: () => import('./features/projects/project-detail').then((m) => m.ProjectDetail),
  },
  {
    path: 'projects/:projectId/invoices/:invoiceId',
    loadComponent: () => import('./features/invoices/invoice-detail').then((m) => m.InvoiceDetailPage),
  },
];
-- An invoice can take a percentage off what its line items add up to. The stored amount remains what
-- is owed, so it is now the subtotal less the discount; existing invoices have no discount.
ALTER TABLE invoice ADD COLUMN discount_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_discount_pct_range CHECK (discount_pct >= 0 AND discount_pct <= 100);
-- An invoice can add a percentage sales tax on top of what is owed after any discount. The stored
-- amount remains what is owed, so it is now the discounted subtotal plus the tax; existing invoices
-- have no tax.
ALTER TABLE invoice ADD COLUMN tax_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_tax_pct_range CHECK (tax_pct >= 0 AND tax_pct <= 100);
-- A lump sum a client pays in one go, split across several of their invoices. Each share is still
-- recorded as an ordinary payment against its invoice, linked back to the lump it came from.
CREATE TABLE client_payment (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT         NOT NULL,
    amount    DECIMAL(12, 2) NOT NULL,
    paid_date DATE           NOT NULL,
    CONSTRAINT client_payment_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT client_payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX client_payment_client_idx ON client_payment (client_id, paid_date);

ALTER TABLE payment ADD COLUMN client_payment_id BIGINT;
ALTER TABLE payment ADD CONSTRAINT payment_client_payment_fk
    FOREIGN KEY (client_payment_id) REFERENCES client_payment (id);
-- A sent invoice can be cancelled (voided) when it was sent by mistake. It stays on record but is no
-- longer owed.
ALTER TABLE invoice DROP CONSTRAINT invoice_status_valid;
ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid
    CHECK (status IN ('DRAFT', 'SENT', 'PARTIAL', 'PAID', 'VOID'));
-- An invoice's status is now worked out from its payments rather than set by hand: a sent invoice
-- becomes PARTIAL once something has been paid against it and PAID once its payments cover it.
ALTER TABLE invoice DROP CONSTRAINT invoice_status_valid;
ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid CHECK (status IN ('DRAFT', 'SENT', 'PARTIAL', 'PAID'));

-- Bring sent invoices in line with the payments already recorded against them. Invoices that were
-- marked paid by hand stay PAID.
UPDATE invoice i SET status = CASE
        WHEN (SELECT SUM(p.amount) FROM payment p WHERE p.invoice_id = i.id) >= i.amount THEN 'PAID'
        ELSE 'PARTIAL'
    END
WHERE i.status = 'SENT' AND EXISTS (SELECT 1 FROM payment p WHERE p.invoice_id = i.id);

