-- A lump sum a client pays in one go, split across several of their invoices. Each share is still
-- recorded as an ordinary payment against its invoice, linked back to the lump it came from.
CREATE TABLE client_payment (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT         NOT NULL,
    amount    DECIMAL(12, 2) NOT NULL,
    paid_date DATE           NOT NULL,
    CONSTRAINT client_payment_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT client_payment_amount_positive CHECK (amount > 0)
);

CREATE INDEX client_payment_client_idx ON client_payment (client_id, paid_date);

ALTER TABLE payment ADD COLUMN client_payment_id BIGINT;
ALTER TABLE payment ADD CONSTRAINT payment_client_payment_fk
    FOREIGN KEY (client_payment_id) REFERENCES client_payment (id);
-- A sent invoice can be cancelled (voided) when it was sent by mistake. It stays on record but is no
-- longer owed.
ALTER TABLE invoice DROP CONSTRAINT invoice_status_valid;
ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid
    CHECK (status IN ('DRAFT', 'SENT', 'PARTIAL', 'PAID', 'VOID'));
-- An invoice's status is now worked out from its payments rather than set by hand: a sent invoice
-- becomes PARTIAL once something has been paid against it and PAID once its payments cover it.
ALTER TABLE invoice DROP CONSTRAINT invoice_status_valid;
ALTER TABLE invoice ADD CONSTRAINT invoice_status_valid CHECK (status IN ('DRAFT', 'SENT', 'PARTIAL', 'PAID'));

-- Bring sent invoices in line with the payments already recorded against them. Invoices that were
-- marked paid by hand stay PAID.
UPDATE invoice i SET status = CASE
        WHEN (SELECT SUM(p.amount) FROM payment p WHERE p.invoice_id = i.id) >= i.amount THEN 'PAID'
        ELSE 'PARTIAL'
    END
WHERE i.status = 'SENT' AND EXISTS (SELECT 1 FROM payment p WHERE p.invoice_id = i.id);

